const DOCES=[{"n":"Mousse de abacate e cacau","t":"5 min · 1 porção","it":[["abacate",1],["cacau",1],["natas",0.6]],"extra":"Adoçante a gosto (sucralose ou stévia) e uma pitada de sal.","st":["Esmaga o meio abacate bem maduro com um garfo ou varinha.","Junta o cacau, as natas (cerca de 2 c. sopa), o adoçante e uma pitada de sal.","Bate até ficar cremoso e leva ao frigorífico 15 min."]},{"n":"Bolo de caneca de coco e cacau","t":"5 min · micro-ondas · 1 porção","it":[["ovo",1],["coco",1.5],["cacau",1],["manteiga",1]],"extra":"Adoçante a gosto e ½ c. chá de fermento.","st":["Derrete a manteiga numa caneca grande (20 s no micro-ondas).","Junta o ovo, 3 c. sopa de coco ralado, o cacau, o adoçante e o fermento e mexe bem.","Micro-ondas 70–90 s, até crescer e ficar firme. Deixa arrefecer 2 min."]},{"n":"Bombons de ginguba e cacau","t":"10 min + 30 min de congelador · 2 bombons","it":[["ginguba",1],["manteiga",0.5],["cacau",0.5]],"extra":"Adoçante a gosto. A receita inteira dá 4 bombons: esta porção é metade.","st":["Tritura 60 g de ginguba torrada até virar pasta (ou usa pasta de amendoim sem açúcar).","Mistura com 1 c. sopa de manteiga derretida, 1 c. sopa de cacau e adoçante.","Faz 4 bolinhas, põe no congelador 30 min e guarda no frigorífico."]},{"n":"Cocadas keto de forno","t":"20 min · 2 cocadas","it":[["ovo",0.5],["coco",2]],"extra":"Adoçante a gosto e umas gotas de baunilha. A receita inteira (1 ovo + 8 c. sopa de coco) dá 4 cocadas.","st":["Mistura 1 ovo, 8 c. sopa de coco ralado, o adoçante e a baunilha.","Faz 4 montinhos num tabuleiro com papel vegetal.","Forno a 180 °C por 12–15 min, até dourarem."]},{"n":"Pudim de ovo de caneca","t":"5 min · micro-ondas · 1 porção","it":[["ovo",1],["natas",1]],"extra":"Adoçante e canela a gosto.","st":["Bate o ovo com as natas, o adoçante e a canela numa caneca.","Micro-ondas em potência média 60–90 s, de 30 em 30 s, até firmar.","Serve frio, polvilhado com canela."]},{"n":"Iogurte gelado de cacau","t":"5 min + 1 h de congelador · 1 porção","it":[["iogurte",1],["cacau",1],["coco",0.5]],"extra":"Adoçante a gosto.","st":["Mistura o iogurte natural com o cacau e o adoçante.","Polvilha com 1 c. sopa de coco ralado.","Congela 1 h e come como gelado."]}];
